def transform(grid):
    # What if 8 falls down through lines?
    # 8 starts at (2,6), falls into row 3? But there are two 8s in the input.
    # What if 8 at (3,5) is the only one because 8 at (2,6) is at the center?
    # What if only the second line's intruder is kept?
    # Let's consider: keep the 8 with the odd row index, or even col index? (3,5) -> row 3 is odd, col 5 is odd.
    R, C = len(grid), len(grid[0])
    out = [[0]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 8 and r % 2 == 1:
                out[r][c] = 8
    return out
